export interface Question {
  id: string;
  question: string;
  options: string[];
  correctAnswer: number; // Index of the correct option
  explanation: string;
}

export interface QuizSet {
  id: string;
  title: string;
  description: string;
  questions: Question[];
  createdAt: number;
  color: string;
}

export type ViewState = 'BOARD' | 'PLAYING' | 'RESULT';

import { GoogleGenAI, Type } from "@google/genai";
import { Question } from "../types";

export const generateQuizFromText = async (text: string, title: string): Promise<Question[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: `Hãy tạo một bộ câu hỏi trắc nghiệm gồm 5-10 câu từ nội dung sau đây: "${text}". 
               Tên chủ đề là: ${title}. 
               Mỗi câu hỏi phải có 4 lựa chọn, chỉ 1 đáp án đúng và có giải thích ngắn gọn.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            },
            correctAnswer: { type: Type.INTEGER, description: "Index of correct option (0-3)" },
            explanation: { type: Type.STRING }
          },
          required: ["question", "options", "correctAnswer", "explanation"]
        }
      },
      thinkingConfig: { thinkingBudget: 0 }
    }
  });

  try {
    const questions: Question[] = JSON.parse(response.text || '[]').map((q: any, index: number) => ({
      ...q,
      id: `q-${Date.now()}-${index}`
    }));
    return questions;
  } catch (error) {
    console.error("Failed to parse AI response:", error);
    throw new Error("Không thể tạo bộ câu hỏi từ nội dung này.");
  }
};

declare const pdfjsLib: any;
declare const mammoth: any;

export const extractTextFromFile = async (file: File): Promise<string> => {
  const extension = file.name.split('.').pop()?.toLowerCase();

  if (extension === 'txt') {
    return await file.text();
  }

  if (extension === 'docx') {
    const arrayBuffer = await file.arrayBuffer();
    const result = await mammoth.extractRawText({ arrayBuffer });
    return result.value;
  }

  if (extension === 'pdf') {
    const arrayBuffer = await file.arrayBuffer();
    pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    let fullText = '';
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items.map((item: any) => item.str).join(' ');
      fullText += pageText + '\n';
    }
    return fullText;
  }

  throw new Error("Định dạng file không được hỗ trợ. Hãy dùng .txt, .pdf hoặc .docx");
};

import React, { useState } from 'react';
import { QuizSet } from '../types';

interface QuizPlayerProps {
  quiz: QuizSet;
  onClose: () => void;
}

const QuizPlayer: React.FC<QuizPlayerProps> = ({ quiz, onClose }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [finished, setFinished] = useState(false);

  const currentQuestion = quiz.questions[currentIdx];

  const handleOptionSelect = (idx: number) => {
    if (isAnswered) return;
    setSelectedOption(idx);
    setIsAnswered(true);
    if (idx === currentQuestion.correctAnswer) {
      setScore(prev => prev + 1);
    }
  };

  const nextQuestion = () => {
    if (currentIdx + 1 < quiz.questions.length) {
      setCurrentIdx(prev => prev + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setFinished(true);
    }
  };

  if (finished) {
    return (
      <div className="fixed inset-0 bg-white z-50 flex flex-col items-center justify-center p-6 text-center animate-in fade-in duration-500">
        <div className="mb-6">
          <div className="w-32 h-32 bg-yellow-100 rounded-full flex items-center justify-center mx-auto mb-4">
             <span className="text-6xl">🏆</span>
          </div>
          <h2 className="text-4xl font-bold text-slate-800 mb-2">Hoàn thành!</h2>
          <p className="text-xl text-slate-600">Bạn đã đạt {score}/{quiz.questions.length} điểm</p>
        </div>
        <div className="flex gap-4">
          <button 
            onClick={onClose}
            className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-lg hover:shadow-indigo-200"
          >
            Quay lại bảng tin
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-indigo-900 z-50 flex flex-col p-4 md:p-8 animate-in slide-in-from-bottom duration-300">
      <div className="max-w-4xl mx-auto w-full flex flex-col h-full">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <div className="text-indigo-200 font-medium">
            Câu {currentIdx + 1} / {quiz.questions.length}
          </div>
          <div className="h-2 flex-1 mx-8 bg-indigo-800 rounded-full overflow-hidden">
            <div 
              className="h-full bg-indigo-400 transition-all duration-500" 
              style={{ width: `${((currentIdx + 1) / quiz.questions.length) * 100}%` }}
            />
          </div>
          <button onClick={onClose} className="text-white opacity-50 hover:opacity-100 text-2xl font-bold">×</button>
        </div>

        {/* Question Area */}
        <div className="flex-1 flex flex-col justify-center items-center text-center space-y-8">
          <h1 className="text-2xl md:text-4xl font-bold text-white px-4 leading-tight">
            {currentQuestion.question}
          </h1>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
            {currentQuestion.options.map((option, idx) => {
              let btnClass = "p-4 md:p-6 text-lg font-semibold rounded-2xl transition-all text-left flex items-center ";

              if (!isAnswered) {
                btnClass += "bg-white/10 hover:bg-white/20 text-white border-2 border-transparent";
              } else {
                if (idx === currentQuestion.correctAnswer) {
                  btnClass += "bg-emerald-500 text-white scale-105 shadow-xl";
                } else if (idx === selectedOption) {
                  btnClass += "bg-rose-500 text-white opacity-90";
                } else {
                  btnClass += "bg-white/5 text-white/50 border-2 border-white/5";
                }
              }

              return (
                <button 
                  key={idx} 
                  onClick={() => handleOptionSelect(idx)}
                  disabled={isAnswered}
                  className={btnClass}
                >
                  <span className="w-8 h-8 rounded-full bg-black/20 flex items-center justify-center mr-4 text-sm">
                    {String.fromCharCode(65 + idx)}
                  </span>
                  {option}
                </button>
              );
            })}
          </div>
        </div>

        {/* Footer info/controls */}
        <div className="h-32 flex flex-col justify-center items-center">
          {isAnswered && (
            <div className="w-full flex flex-col items-center animate-in fade-in slide-in-from-bottom-4">
              <p className="text-indigo-200 mb-4 text-center text-sm italic">
                {currentQuestion.explanation}
              </p>
              <button 
                onClick={nextQuestion}
                className="px-12 py-4 bg-white text-indigo-900 rounded-2xl font-bold hover:bg-indigo-50 transition-all shadow-xl"
              >
                Tiếp tục
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default QuizPlayer;

import React, { useState, useEffect, useCallback } from 'react';
import { QuizSet } from './types';
import { extractTextFromFile } from './services/fileService';
import { generateQuizFromText } from './services/geminiService';
import QuizPlayer from './components/QuizPlayer';

const COLORS = [
  'bg-pink-100 border-pink-200',
  'bg-blue-100 border-blue-200',
  'bg-amber-100 border-amber-200',
  'bg-emerald-100 border-emerald-200',
  'bg-purple-100 border-purple-200',
  'bg-rose-100 border-rose-200',
];

const App: React.FC = () => {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeQuiz, setActiveQuiz] = useState<QuizSet | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Load from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('edu_quizzes');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load local storage", e);
      }
    }
  }, []);

  // Save to localStorage
  useEffect(() => {
    localStorage.setItem('edu_quizzes', JSON.stringify(quizzes));
  }, [quizzes]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    setError(null);

    try {
      const text = await extractTextFromFile(file);
      if (text.length < 50) {
        throw new Error("Nội dung tài liệu quá ngắn để tạo bộ câu hỏi.");
      }

      const title = file.name.replace(/\.[^/.]+$/, "");
      const questions = await generateQuizFromText(text, title);

      const newQuiz: QuizSet = {
        id: `quiz-${Date.now()}`,
        title,
        description: `Bộ câu hỏi được tạo từ ${file.name}`,
        questions,
        createdAt: Date.now(),
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
      };

      setQuizzes(prev => [newQuiz, ...prev]);
    } catch (err: any) {
      setError(err.message || "Đã có lỗi xảy ra khi xử lý tài liệu.");
    } finally {
      setIsUploading(false);
      // Reset input
      event.target.value = '';
    }
  };

  const deleteQuiz = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Bạn có chắc muốn xóa bộ câu hỏi này?")) {
      setQuizzes(prev => prev.filter(q => q.id !== id));
    }
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Navbar */}
      <nav className="sticky top-0 z-40 bg-white/80 backdrop-blur-md border-b border-slate-200 px-4 md:px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white font-black text-xl shadow-lg shadow-indigo-200">
            E
          </div>
          <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">
            EduAI Master
          </h1>
        </div>

        <label className="cursor-pointer bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-full font-semibold transition-all shadow-md active:scale-95 flex items-center gap-2">
          <span className="text-xl">+</span>
          <span>Tạo bộ câu hỏi mới</span>
          <input 
            type="file" 
            className="hidden" 
            accept=".pdf,.docx,.txt"
            onChange={handleFileUpload}
            disabled={isUploading}
          />
        </label>
      </nav>

      {/* Hero Section */}
      <div className="max-w-7xl mx-auto px-4 md:px-8 py-10">
        <div className="mb-10 text-center md:text-left">
          <h2 className="text-4xl md:text-5xl font-black text-slate-800 mb-4">
            Biến tài liệu thành <span className="text-indigo-600">Trò chơi</span> kiến thức
          </h2>
          <p className="text-lg text-slate-500 max-w-2xl">
            Tải lên file PDF, DOCX hoặc TXT. AI sẽ phân tích và tạo bộ trắc nghiệm thông minh trong vài giây. 
            Ôn tập hiệu quả phong cách Padlet & Quizizz.
          </p>
        </div>

        {error && (
          <div className="mb-8 p-4 bg-rose-50 border border-rose-200 text-rose-700 rounded-2xl flex items-center gap-3">
            <span className="text-xl">⚠️</span>
            {error}
          </div>
        )}

        {isUploading && (
          <div className="mb-10 p-12 bg-white border-2 border-dashed border-indigo-200 rounded-3xl flex flex-col items-center text-center animate-pulse">
            <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
            <h3 className="text-xl font-bold text-slate-700">Đang đọc tài liệu & tạo câu hỏi...</h3>
            <p className="text-slate-400 mt-2">AI đang trích xuất nội dung quan trọng cho bạn.</p>
          </div>
        )}

        {/* Masonry Grid like Padlet */}
        <div className="masonry-grid">
          {quizzes.length === 0 && !isUploading ? (
            <div className="col-span-full py-20 text-center">
              <div className="text-8xl mb-6">📚</div>
              <h3 className="text-2xl font-bold text-slate-400">Chưa có bộ ôn tập nào</h3>
              <p className="text-slate-400 mt-2">Bắt đầu bằng cách tải lên tài liệu đầu tiên của bạn!</p>
            </div>
          ) : (
            quizzes.map(quiz => (
              <div 
                key={quiz.id}
                onClick={() => setActiveQuiz(quiz)}
                className={`group relative p-6 rounded-3xl border-2 transition-all hover:scale-[1.02] hover:shadow-2xl cursor-pointer ${quiz.color} shadow-sm`}
              >
                <div className="flex justify-between items-start mb-4">
                  <span className="bg-white/50 px-3 py-1 rounded-full text-xs font-bold text-slate-600">
                    {quiz.questions.length} Câu hỏi
                  </span>
                  <button 
                    onClick={(e) => deleteQuiz(quiz.id, e)}
                    className="opacity-0 group-hover:opacity-100 p-2 hover:bg-rose-500 hover:text-white rounded-full transition-all text-slate-400"
                  >
                    🗑️
                  </button>
                </div>
                <h3 className="text-xl font-bold text-slate-800 mb-2 line-clamp-2">
                  {quiz.title}
                </h3>
                <p className="text-slate-600 text-sm line-clamp-3 mb-6 leading-relaxed">
                  {quiz.description}
                </p>
                <div className="flex items-center justify-between text-xs text-slate-400 mt-auto">
                   <span>📅 {new Date(quiz.createdAt).toLocaleDateString('vi-VN')}</span>
                   <span className="flex items-center gap-1 font-bold text-indigo-600">
                      Chơi ngay <span className="text-lg">➔</span>
                   </span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Floating Action Button (Mobile) */}
      <div className="fixed bottom-6 right-6 md:hidden">
        <label className="w-16 h-16 bg-indigo-600 rounded-full flex items-center justify-center text-white text-3xl shadow-2xl cursor-pointer">
          +
          <input 
            type="file" 
            className="hidden" 
            accept=".pdf,.docx,.txt"
            onChange={handleFileUpload}
            disabled={isUploading}
          />
        </label>
      </div>

      {/* Fullscreen Quiz Player */}
      {activeQuiz && (
        <QuizPlayer 
          quiz={activeQuiz} 
          onClose={() => setActiveQuiz(null)} 
        />
      )}
    </div>
  );
};

export default App;

