import { GoogleGenAI, Type } from "@google/genai";
import { Question } from "../types";

export const generateQuizFromText = async (text: string, title: string): Promise<Question[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `
    BẠN LÀ MỘT CHUYÊN GIA BIÊN SOẠN ĐỀ THI TRẮC NGHIỆM.
    NHIỆM VỤ CỦA BẠN:
    1. Quét toàn bộ văn bản sau: "${text.substring(0, 10000)}" (Cắt ngắn nếu quá dài).
    2. TRÍCH XUẤT: Tìm các câu hỏi trắc nghiệm có sẵn (thường có dạng Câu 1, Câu 2, hoặc có các lựa chọn A, B, C, D).
    3. TỔNG HỢP: Nếu văn bản là nội dung lý thuyết, hãy tự soạn các câu hỏi trắc nghiệm bao quát TOÀN BỘ các ý chính của tài liệu.
    4. YÊU CẦU: Mỗi câu hỏi phải có 4 lựa chọn, chỉ có 1 đáp án đúng duy nhất.
    5. ĐỊNH DẠNG TRẢ VỀ: JSON array.

    Tiêu đề chủ đề: ${title}
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Mảng chứa 4 lựa chọn trắc nghiệm"
            },
            correctAnswer: { type: Type.INTEGER, description: "Index của đáp án đúng (0-3)" },
            explanation: { type: Type.STRING, description: "Giải thích ngắn gọn tại sao đáp án đó đúng" }
          },
          required: ["question", "options", "correctAnswer", "explanation"]
        }
      }
    }
  });

  try {
    const questions: Question[] = JSON.parse(response.text || '[]').map((q: any, index: number) => ({
      ...q,
      id: `q-${Date.now()}-${index}`
    }));
    return questions;
  } catch (error) {
    console.error("Failed to parse AI response:", error);
    throw new Error("Không thể xử lý nội dung này. Vui lòng thử lại với file khác.");
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { QuizSet } from '../types';

interface QuizPlayerProps {
  quiz: QuizSet;
  onClose: () => void;
}

const QuizPlayer: React.FC<QuizPlayerProps> = ({ quiz, onClose }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [finished, setFinished] = useState(false);
  const [streak, setStreak] = useState(0);

  const correctSfx = useRef(new Audio('https://actions.google.com/sounds/v1/cartoon/clink_clack.ogg'));
  const wrongSfx = useRef(new Audio('https://actions.google.com/sounds/v1/cartoon/boing.ogg'));
  const winSfx = useRef(new Audio('https://actions.google.com/sounds/v1/foley/wind_chime_fast.ogg'));

  const currentQuestion = quiz.questions[currentIdx];

  const handleOptionSelect = (idx: number) => {
    if (isAnswered) return;
    setSelectedOption(idx);
    setIsAnswered(true);

    if (idx === currentQuestion.correctAnswer) {
      setScore(prev => prev + 1);
      setStreak(prev => prev + 1);
      correctSfx.current.play().catch(() => {});
    } else {
      setStreak(0);
      wrongSfx.current.play().catch(() => {});
    }
  };

  const nextQuestion = () => {
    if (currentIdx + 1 < quiz.questions.length) {
      setCurrentIdx(prev => prev + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      setFinished(true);
      winSfx.current.play().catch(() => {});
    }
  };

  if (finished) {
    return (
      <div className="fixed inset-0 bg-[#0f172a] z-50 flex flex-col items-center justify-center p-6 text-center animate__animated animate__fadeIn">
        <div className="mb-10 relative">
          <div className="w-48 h-48 bg-yellow-400/20 rounded-full flex items-center justify-center mx-auto mb-4 animate__animated animate__bounceIn">
             <span className="text-8xl floating">🏆</span>
          </div>
          <div className="absolute -top-4 -right-4 bg-indigo-600 text-white px-4 py-2 rounded-full font-bold shadow-xl animate__animated animate__jackInTheBox">
            SIÊU CẤP!
          </div>
        </div>

        <h2 className="text-5xl font-black text-white mb-2">Hoàn thành!</h2>
