  const bgMusic = useRef(new Audio('https://www.soundhelix.com/examples/mp3/SoundHelix-Song-8.mp3')); // Lofi-ish style

  useEffect(() => {
    bgMusic.current.loop = true;
    bgMusic.current.volume = 0.3;

