import { GoogleGenAI, Type } from "@google/genai";
import { Question } from "../types";

export const generateQuizFromText = async (text: string, title: string): Promise<Question[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `
    BẠN LÀ MỘT CHUYÊN GIA BIÊN SOẠN ĐỀ THI TRẮC NGHIỆM.
    NHIỆM VỤ CỦA BẠN:
    1. Quét toàn bộ văn bản sau: "${text.substring(0, 10000)}" (Cắt ngắn nếu quá dài).
    2. TRÍCH XUẤT: Tìm các câu hỏi trắc nghiệm có sẵn (thường có dạng Câu 1, Câu 2, hoặc có các lựa chọn A, B, C, D).
    3. TỔNG HỢP: Nếu văn bản là nội dung lý thuyết, hãy tự soạn các câu hỏi trắc nghiệm bao quát TOÀN BỘ các ý chính của tài liệu.
    4. YÊU CẦU: Mỗi câu hỏi phải có 4 lựa chọn, chỉ có 1 đáp án đúng duy nhất.
    5. ĐỊNH DẠNG TRẢ VỀ: JSON array.

    Tiêu đề chủ đề: ${title}
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Mảng chứa 4 lựa chọn trắc nghiệm"
            },
            correctAnswer: { type: Type.INTEGER, description: "Index của đáp án đúng (0-3)" },
            explanation: { type: Type.STRING, description: "Giải thích ngắn gọn tại sao đáp án đó đúng" }
          },
          required: ["question", "options", "correctAnswer", "explanation"]
        }
      },
      // Cung cấp thinkingBudget vì Gemini 3 series có thể yêu cầu điều này trong một số môi trường
      thinkingConfig: { thinkingBudget: 1024 }
    }
  });

  try {
    const questions: Question[] = JSON.parse(response.text || '[]').map((q: any, index: number) => ({
      ...q,
      id: `q-${Date.now()}-${index}`
    }));
    return questions;
  } catch (error) {
    console.error("Failed to parse AI response:", error);
    throw new Error("Không thể xử lý nội dung này. Vui lòng thử lại với file khác.");
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { QuizSet } from './types';
import { extractTextFromFile } from './services/fileService';
import { generateQuizFromText } from './services/geminiService';
import QuizPlayer from './components/QuizPlayer';

const COLORS = [
  'bg-gradient-to-br from-pink-500/20 to-rose-500/20 border-pink-500/30 text-pink-100',
  'bg-gradient-to-br from-blue-500/20 to-indigo-500/20 border-blue-500/30 text-blue-100',
  'bg-gradient-to-br from-amber-500/20 to-orange-500/20 border-amber-500/30 text-amber-100',
  'bg-gradient-to-br from-emerald-500/20 to-teal-500/20 border-emerald-500/30 text-emerald-100',
  'bg-gradient-to-br from-purple-500/20 to-violet-500/20 border-purple-500/30 text-purple-100',
];

const App: React.FC = () => {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeQuiz, setActiveQuiz] = useState<QuizSet | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMusicPlaying, setIsMusicPlaying] = useState(false);

  const bgMusic = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    // Chỉ khởi tạo Audio khi component mount để tránh lỗi Uncaught nếu server media không phản hồi
    bgMusic.current = new Audio('https://www.soundhelix.com/examples/mp3/SoundHelix-Song-8.mp3');
    bgMusic.current.loop = true;
    bgMusic.current.volume = 0.3;

    // Kiểm tra link chia sẻ trong URL
    const params = new URLSearchParams(window.location.search);
    const sharedData = params.get('share');
    if (sharedData) {
      try {
        // Sử dụng try-catch để bắt lỗi Uncaught DOMException nếu sharedData không phải base64 hợp lệ
        const decodedString = atob(sharedData);
        const decoded = JSON.parse(decodedString);
        if (decoded && decoded.id && decoded.questions) {
          setActiveQuiz(decoded);
          setQuizzes(prev => {
            if (prev.find(q => q.id === decoded.id)) return prev;
            return [decoded, ...prev];
          });
        }
      } catch (e) {
        console.error("Lỗi giải mã link chia sẻ hoặc format không hợp lệ:", e);
        setError("Link chia sẻ không hợp lệ hoặc đã hết hạn.");
      } finally {
        // Clear param để tránh loop và giữ URL sạch
        window.history.replaceState({}, document.title, window.location.pathname);
      }
    }

    const saved = localStorage.getItem('edu_quizzes_v2');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load local storage", e);
      }
    }

    return () => {
      if (bgMusic.current) {
        bgMusic.current.pause();
        bgMusic.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (quizzes.length > 0) {
      localStorage.setItem('edu_quizzes_v2', JSON.stringify(quizzes));
    }
  }, [quizzes]);

  const toggleMusic = () => {
    if (!bgMusic.current) return;

    if (isMusicPlaying) {
      bgMusic.current.pause();
    } else {
      bgMusic.current.play().catch((err) => {
        console.warn("Autoplay blocked or audio error:", err);
        alert("Vui lòng tương tác với trang web để bật nhạc!");
      });
    }
    setIsMusicPlaying(!isMusicPlaying);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    setError(null);

    try {
      const text = await extractTextFromFile(file);
      const title = file.name.replace(/\.[^/.]+$/, "");
      const questions = await generateQuizFromText(text, title);

      const newQuiz: QuizSet = {
        id: `quiz-${Date.now()}`,
        title,
