          normalizedQuiz = decoded;
        } 
        // Trường hợp 2: Format mới (Minified keys - t, d, q, o, a, e)
        else if (decoded.q && Array.isArray(decoded.q)) {
          normalizedQuiz = {
            id: decoded.id || `share-${Date.now()}`,
            title: decoded.t || "Bộ đề được chia sẻ",
            description: decoded.d || "Không có mô tả",
            questions: decoded.q.map((item: any, idx: number) => ({
              id: `q-${Date.now()}-${idx}`,
              question: item.q,
              options: item.o,
              correctAnswer: item.a,
              explanation: item.e
            })),
            createdAt: Date.now(),
            color: COLORS[Math.floor(Math.random() * COLORS.length)]
          };
        }

        if (normalizedQuiz) {
          const finalQuiz = normalizedQuiz; // Fix type narrowing
          setActiveQuiz(finalQuiz);
          setQuizzes(prev => {
            if (prev.find(q => q.id === finalQuiz.id)) return prev;
            return [finalQuiz, ...prev];
          });
          // Xóa param share trên URL để tránh duplicate khi reload
          window.history.replaceState({}, document.title, window.location.pathname);
        } else {
           throw new Error("Cấu trúc dữ liệu không hợp lệ.");
        }
      } catch (e) {
        console.error("Lỗi xử lý link chia sẻ:", e);
        setError("Link chia sẻ này bị hỏng hoặc đã hết hạn. Vui lòng xin lại link mới.");
        // Vẫn xóa URL lỗi để người dùng có thể dùng app bình thường
        window.history.replaceState({}, document.title, window.location.pathname);
      }
    };

    processSharedLink();

    const saved = localStorage.getItem('edu_quizzes_v2');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load local storage", e);
      }
    }

    return () => {
      if (bgMusic.current) {
        bgMusic.current.pause();
        bgMusic.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (quizzes.length > 0) {
      localStorage.setItem('edu_quizzes_v2', JSON.stringify(quizzes));
    }
  }, [quizzes]);

  const toggleMusic = () => {
    if (!bgMusic.current) return;
    if (isMusicPlaying) {
      bgMusic.current.pause();
    } else {
      bgMusic.current.play().catch(() => alert("Bấm vào trang web trước khi bật nhạc!"));
    }
    setIsMusicPlaying(!isMusicPlaying);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    setError(null);

    try {
      const text = await extractTextFromFile(file);
      const title = file.name.replace(/\.[^/.]+$/, "");
      const questions = await generateQuizFromText(text, title);

      const newQuiz: QuizSet = {
        id: `quiz-${Date.now()}`,
