        description: `Trích xuất từ: ${file.name}. AI đã ưu tiên giữ nguyên các câu hỏi gốc tìm thấy trong tài liệu.`,
        questions,
        createdAt: Date.now(),
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
      };

