              <span className="text-[10px] font-bold">Nhập mã</span>
            </button>
         </div>
      </div>

      {activeQuiz && (
        <QuizPlayer quiz={activeQuiz} onClose={() => setActiveQuiz(null)} />
      )}
    </div>
  );
};

