import React, { useState, useEffect, useRef } from 'react';
import { QuizSet, Question } from './types';
import { extractTextFromFile } from './services/fileService';
import { generateQuizFromText } from './services/geminiService';
import QuizPlayer from './components/QuizPlayer';
import * as fflate from 'fflate';

declare const QRious: any;

const COLORS = [
  'bg-gradient-to-br from-pink-500/20 to-rose-500/20 border-pink-500/30 text-pink-100',
  'bg-gradient-to-br from-blue-500/20 to-indigo-500/20 border-blue-500/30 text-blue-100',
  'bg-gradient-to-br from-amber-500/20 to-orange-500/20 border-amber-500/30 text-amber-100',
  'bg-gradient-to-br from-emerald-500/20 to-teal-500/20 border-emerald-500/30 text-emerald-100',
  'bg-gradient-to-br from-purple-500/20 to-violet-500/20 border-purple-500/30 text-purple-100',
];

/**
 * ULTRA COMPRESSION v2:
 * 1. Remove explanation if string is too long to save space (Optional strategy, currently keeping it but compressing harder)
 * 2. Structure: [version, title, questions_array] (Description removed from code to save space)
 */
const compressToCode = (quiz: QuizSet): string => {
  try {
    // Minify dữ liệu: Chỉ lấy câu hỏi, đáp án, index đúng. 
    // Format: [version, title, [Q, Options, A, Expl]]
    const minified = [
      2, // Version 2
      quiz.title,
      quiz.questions.map(q => [q.question, q.options, q.correctAnswer, q.explanation])
    ];

    const str = JSON.stringify(minified);
    const buf = new TextEncoder().encode(str);
    // Level 9 compression
    const compressed = fflate.zlibSync(buf, { level: 9 });

    let binary = "";
    for (let i = 0; i < compressed.length; i++) {
      binary += String.fromCharCode(compressed[i]);
    }
    // Base64 URL Safe
    return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  } catch (e) {
    console.error("Compression error:", e);
    throw new Error("Lỗi nén dữ liệu.");
  }
};

const decompressFromCode = (code: string): QuizSet | null => {
  try {
    let base64 = code.trim().replace(/-/g, '+').replace(/_/g, '/');
    while (base64.length % 4) base64 += '=';

    const binary = atob(base64);
    const buf = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      buf[i] = binary.charCodeAt(i);
    }

    const decompressed = fflate.unzlibSync(buf);
    const str = new TextDecoder().decode(decompressed);
    const data = JSON.parse(str);

    // Xử lý version 2 (Mới)
    if (Array.isArray(data) && data[0] === 2) {
       return {
         id: `import-${Date.now()}`,
         title: data[1],
         description: "Được chia sẻ qua mã Code",
         questions: data[2].map((q: any, idx: number) => ({
           id: `q-${Date.now()}-${idx}`,
           question: q[0],
           options: q[1],
           correctAnswer: q[2],
           explanation: q[3] || "Không có giải thích chi tiết."
         })),
         createdAt: Date.now(),
         color: COLORS[Math.floor(Math.random() * COLORS.length)]
       };
    }

    // Fallback version 1 (Cũ)
    if (Array.isArray(data) && data[0] === 1) {
       return {
         id: `import-${Date.now()}`,
         title: data[1],
         description: data[2],
         questions: data[3].map((q: any, idx: number) => ({
           id: `q-${Date.now()}-${idx}`,
           question: q[0],
           options: q[1],
           correctAnswer: q[2],
           explanation: q[3]
         })),
         createdAt: Date.now(),
         color: COLORS[Math.floor(Math.random() * COLORS.length)]
       };
    }

    return null;
  } catch (e) {
    console.error("Decompression error:", e);
    return null;
  }
};

const App: React.FC = () => {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeQuiz, setActiveQuiz] = useState<QuizSet | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMusicPlaying, setIsMusicPlaying] = useState(false);

  // UI States
  const [view, setView] = useState<'HOME' | 'IMPORT' | 'SHARE'>('HOME');
  const [shareData, setShareData] = useState<{code: string, url: string | null} | null>(null);
  const [importCode, setImportCode] = useState('');

  const bgMusic = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Nhạc Lofi Chill
    bgMusic.current = new Audio('https://cdn.pixabay.com/audio/2022/05/27/audio_1808fbf07a.mp3');
    bgMusic.current.loop = true;
    bgMusic.current.volume = 0.3;

    const params = new URLSearchParams(window.location.search);
    const sharedCode = params.get('c');
    if (sharedCode) {
      handleImport(sharedCode);
      window.history.replaceState({}, document.title, window.location.pathname);
    }

    const saved = localStorage.getItem('edu_quizzes_v2');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load local storage", e);
      }
    }

    return () => {
      if (bgMusic.current) {
        bgMusic.current.pause();
        bgMusic.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (quizzes.length > 0) {
      localStorage.setItem('edu_quizzes_v2', JSON.stringify(quizzes));
    }
  }, [quizzes]);

  // Effect vẽ QR Code khi mở modal Share
  useEffect(() => {
    if (view === 'SHARE' && shareData && typeof QRious !== 'undefined') {
      try {
        const qrCanvas = document.getElementById('qr-code');
        if (qrCanvas) {
          // Nếu có URL thì dùng URL, nếu không thì dùng Code (nén)
          const valueToEncode = shareData.url || shareData.code;

          // Giới hạn QR capacity (nếu text quá dài QR sẽ lỗi hoặc quá dày đặc)
          // Zalo quét tốt nhất < 1000 ký tự. Nếu code > 1500 ký tự, QR có thể khó quét.
          if (valueToEncode.length < 2500) {
              new QRious({
                element: qrCanvas,
                value: valueToEncode,
                size: 250,
                level: 'L',
                backgroundAlpha: 0,
                foreground: '#ffffff'
              });
          } else {
             // Nếu quá dài, không vẽ QR
          }
        }
      } catch(e) { console.error(e); }
    }
  }, [view, shareData]);

  const toggleMusic = () => {
    if (!bgMusic.current) return;
    if (isMusicPlaying) {
      bgMusic.current.pause();
    } else {
      bgMusic.current.play().catch(() => {});
    }
    setIsMusicPlaying(!isMusicPlaying);
  };

  const handleImport = (code: string) => {
    if (!code) return;
    const quiz = decompressFromCode(code);
    if (quiz) {
      setQuizzes(prev => {
         // Tránh trùng lặp ID
         if (prev.some(q => q.title === quiz.title && q.questions.length === quiz.questions.length)) return prev;
         return [quiz, ...prev];
      });
      setActiveQuiz(quiz);
      setView('HOME');
      setImportCode('');
      alert(`Đã nhập thành công: ${quiz.title}`);
    } else {
      alert("Mã không hợp lệ hoặc bị lỗi!");
    }
  };

  const handlePasteAndImport = async () => {
    try {
      const text = await navigator.clipboard.readText();
      setImportCode(text);
      if (text.length > 20) {
          handleImport(text);
      }
    } catch (err) {
      alert("Không thể truy cập bộ nhớ đệm. Hãy dán thủ công.");
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    setView('HOME');
    setError(null);

    try {
      const text = await extractTextFromFile(file);
      const title = file.name.replace(/\.[^/.]+$/, "");
      const questions = await generateQuizFromText(text, title);

      const newQuiz: QuizSet = {
        id: `quiz-${Date.now()}`,
        title,
        description: `Từ file: ${file.name}`,
        questions,
        createdAt: Date.now(),
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
      };

      setQuizzes(prev => [newQuiz, ...prev]);
    } catch (err: any) {
      setError(err.message || "Lỗi xử lý file.");
    } finally {
      setIsUploading(false);
      event.target.value = '';
    }
  };

  const openShareModal = (quiz: QuizSet, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      const code = compressToCode(quiz);
      const url = code.length < 2000 
        ? `${window.location.origin}${window.location.pathname}?c=${code}`
        : null;

      setShareData({ code, url });
      setView('SHARE');
    } catch (e) {
      alert("Lỗi tạo mã chia sẻ");
    }
  };

  const deleteQuiz = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Xóa bộ đề này?")) {
      const updated = quizzes.filter(q => q.id !== id);
      setQuizzes(updated);
      localStorage.setItem('edu_quizzes_v2', JSON.stringify(updated));
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-100 relative overflow-hidden flex flex-col">
      {/* Background Effects */}
      <div className="fixed inset-0 pointer-events-none z-0">
         <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/40 rounded-full blur-[100px]"></div>
         <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/40 rounded-full blur-[100px]"></div>
      </div>

      {/* Top Bar */}
