import React, { useState, useEffect, useRef } from 'react';
import { QuizSet, Question } from '../types';

interface QuizPlayerProps {
  quiz: QuizSet;
  onClose: () => void;
}

// Hàm xáo trộn mảng (Fisher-Yates Shuffle)
const shuffleArray = <T,>(array: T[]): T[] => {
  const newArr = [...array];
  for (let i = newArr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
  }
  return newArr;
};

// FIX: Thuật toán xáo trộn đáp án an toàn
const shuffleQuestionOptions = (question: Question): Question => {
  const optionsWithStatus = question.options.map((opt, index) => ({
    text: opt,
    isCorrect: index === question.correctAnswer
  }));

  const shuffledOptionsWithStatus = shuffleArray(optionsWithStatus);
  const newOptions = shuffledOptionsWithStatus.map(o => o.text);
  const newCorrectIndex = shuffledOptionsWithStatus.findIndex(o => o.isCorrect);

  return {
    ...question,
    options: newOptions,
    correctAnswer: newCorrectIndex,
  };
};

const QuizPlayer: React.FC<QuizPlayerProps> = ({ quiz, onClose }) => {
  const [playableQuestions, setPlayableQuestions] = useState<Question[]>([]);
  const [currentIdx, setCurrentIdx] = useState(0);
  const [score, setScore] = useState(0);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [finished, setFinished] = useState(false);
  const [streak, setStreak] = useState(0);
  const [hasClaimed, setHasClaimed] = useState(false); // New state: Đã khiếu nại chưa

  const correctSfx = useRef(new Audio('https://actions.google.com/sounds/v1/cartoon/clink_clack.ogg'));
  const wrongSfx = useRef(new Audio('https://actions.google.com/sounds/v1/cartoon/boing.ogg'));
  const winSfx = useRef(new Audio('https://actions.google.com/sounds/v1/foley/wind_chime_fast.ogg'));
  const claimSfx = useRef(new Audio('https://actions.google.com/sounds/v1/cartoon/pop.ogg'));

  useEffect(() => {
    const shuffledQs = shuffleArray(quiz.questions);
    const fullyShuffled = shuffledQs.map(shuffleQuestionOptions);
    setPlayableQuestions(fullyShuffled);
  }, [quiz]);

  if (playableQuestions.length === 0) return null;

  const currentQuestion = playableQuestions[currentIdx];

  const handleOptionSelect = (idx: number) => {
    if (isAnswered) return;
    setSelectedOption(idx);
    setIsAnswered(true);
    setHasClaimed(false);

    if (idx === currentQuestion.correctAnswer) {
      setScore(prev => prev + 1);
      setStreak(prev => prev + 1);
      correctSfx.current.play().catch(() => {});
    } else {
      setStreak(0);
      wrongSfx.current.play().catch(() => {});
    }
  };

  // Tính năng: Khiếu nại (Tôi đúng)
  const handleClaimCorrect = () => {
    if (!isAnswered || hasClaimed) return;
    setScore(prev => prev + 1);
    setStreak(prev => prev + 1); // Khôi phục streak (tạm tính là 1 nếu trước đó về 0)
    setHasClaimed(true);
    claimSfx.current.play().catch(() => {});
  };

  const nextQuestion = () => {
    if (currentIdx + 1 < playableQuestions.length) {
      setCurrentIdx(prev => prev + 1);
      setSelectedOption(null);
      setIsAnswered(false);
      setHasClaimed(false);
    } else {
      setFinished(true);
      winSfx.current.play().catch(() => {});
    }
  };

  if (finished) {
    return (
      <div className="fixed inset-0 bg-[#0f172a] z-50 flex flex-col items-center justify-center p-6 text-center animate__animated animate__fadeIn">
        <div className="mb-10 relative">
          <div className="w-48 h-48 bg-yellow-400/20 rounded-full flex items-center justify-center mx-auto mb-4 animate__animated animate__bounceIn">
             <span className="text-8xl floating">🏆</span>
          </div>
          <div className="absolute -top-4 -right-4 bg-indigo-600 text-white px-4 py-2 rounded-full font-bold shadow-xl animate__animated animate__jackInTheBox">
            KẾT QUẢ
          </div>
        </div>

        <h2 className="text-5xl font-black text-white mb-2">Hoàn thành!</h2>
        <p className="text-2xl text-indigo-300 mb-8">Bạn đã trả lời đúng {score}/{playableQuestions.length} câu</p>

        <div className="flex gap-4">
          <button 
            onClick={onClose}
            className="px-10 py-4 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-2xl font-bold hover:scale-105 transition-all shadow-2xl shadow-indigo-500/40"
          >
            Về bảng tin
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-[#0f172a] z-50 flex flex-col p-4 md:p-8 animate__animated animate__slideInUp overflow-y-auto">
      <div className="max-w-4xl mx-auto w-full flex flex-col min-h-full">
        {/* Header */}
        <div className="flex justify-between items-center mb-4 bg-white/5 p-4 rounded-2xl backdrop-blur-md sticky top-0 z-10">
          <div className="flex flex-col">
            <span className="text-indigo-400 text-xs font-bold uppercase tracking-widest">Đang trả lời</span>
            <div className="text-white font-black text-xl">
              Câu {currentIdx + 1} <span className="text-slate-500 font-normal">/ {playableQuestions.length}</span>
            </div>
          </div>

          <div className="flex-1 mx-4 md:mx-8 h-3 bg-slate-800 rounded-full overflow-hidden shadow-inner">
            <div 
              className="h-full bg-gradient-to-r from-indigo-500 to-purple-500 transition-all duration-1000 ease-out" 
              style={{ width: `${((currentIdx + 1) / playableQuestions.length) * 100}%` }}
            />
          </div>

          <div className="flex items-center gap-4">
             {streak > 1 && (
               <div className="hidden md:flex items-center gap-1 bg-orange-500 text-white px-3 py-1 rounded-full font-bold animate__animated animate__pulse animate__infinite">
                 🔥 {streak}x
               </div>
             )}
             <button onClick={onClose} className="text-white/40 hover:text-white text-3xl transition-colors">×</button>
          </div>
        </div>

        {/* Question Area */}
        <div className="flex-1 flex flex-col justify-center items-center text-center space-y-6 md:space-y-10 py-2">
          <div className={`transition-all duration-500 ${isAnswered ? 'scale-95 opacity-80' : 'scale-100'}`}>
             <h1 className="text-2xl md:text-4xl font-black text-white px-2 leading-tight drop-shadow-2xl">
              {currentQuestion.question}
            </h1>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
            {currentQuestion.options.map((option, idx) => {
              let btnClass = "relative p-5 md:p-8 text-lg font-bold rounded-3xl transition-all text-left flex items-center border-4 group ";

              if (!isAnswered) {
                btnClass += "bg-white/5 hover:bg-white/10 text-white border-white/10 hover:border-indigo-500/50 hover:-translate-y-1 active:scale-95";
              } else {
                if (idx === currentQuestion.correctAnswer) {
                  // Đáp án đúng (theo máy)
                  btnClass += "bg-emerald-500 border-emerald-400 text-white scale-105 shadow-[0_0_40px_rgba(16,185,129,0.4)]";
                } else if (idx === selectedOption) {
                  // Đáp án bạn chọn
                  if (hasClaimed) {
                     // Nếu đã khiếu nại -> Biến thành màu xanh dương (được chấp nhận)
                     btnClass += "bg-blue-500 border-blue-400 text-white animate__animated animate__tada";
                  } else {
                     // Nếu chưa khiếu nại -> Màu đỏ (Sai)
                     btnClass += "bg-rose-500 border-rose-400 text-white animate__animated animate__shakeX";
                  }
                } else {
                  btnClass += "bg-white/5 border-transparent text-white/30 scale-95 opacity-40";
                }
              }

              return (
                <button 
                  key={idx} 
                  onClick={() => handleOptionSelect(idx)}
                  disabled={isAnswered}
                  className={btnClass}
                >
                  <span className={`w-10 h-10 rounded-xl flex items-center justify-center mr-4 text-sm transition-colors ${!isAnswered ? 'bg-white/10 group-hover:bg-indigo-500' : 'bg-black/20'}`}>
                    {String.fromCharCode(65 + idx)}
                  </span>
                  <span className="flex-1 text-sm md:text-lg">{option}</span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Feedback Area */}
        <div className="min-h-32 flex flex-col justify-center items-center mt-6 pb-20 md:pb-0">
          {isAnswered && (
            <div className="w-full flex flex-col items-center animate__animated animate__fadeInUp">

              {/* Nút Khiếu nại - Chỉ hiện khi chọn sai và chưa khiếu nại */}
              {selectedOption !== currentQuestion.correctAnswer && !hasClaimed && (
                <button 
                  onClick={handleClaimCorrect}
                  className="mb-4 px-4 py-2 bg-blue-600/30 border border-blue-500 text-blue-200 text-xs font-bold rounded-full hover:bg-blue-600 hover:text-white transition-colors flex items-center gap-2"
                >
                  🤔 <span>Đáp án máy sai? Bấm để <b>Cộng điểm</b></span>
                </button>
              )}

              {hasClaimed && (
                 <div className="mb-4 text-blue-400 text-sm font-bold animate__animated animate__fadeIn">
                   ✅ Đã ghi nhận bạn đúng! (+1 Điểm)
                 </div>
              )}

              <div className="bg-white/5 backdrop-blur-xl p-4 rounded-2xl border border-white/10 mb-6 max-w-2xl w-full">
                <p className="text-indigo-200 text-center text-sm md:text-base">
                   <span className="font-bold text-white block mb-1 uppercase tracking-tighter">💡 Giải thích:</span>
                   {currentQuestion.explanation}
                </p>
              </div>
              <button 
                onClick={nextQuestion}
                className="w-full md:w-auto px-10 py-4 bg-white text-indigo-900 rounded-2xl font-black text-lg hover:bg-indigo-50 transition-all shadow-[0_20px_50px_rgba(255,255,255,0.2)] active:scale-95"
              >
                CÂU TIẾP THEO ➔
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default QuizPlayer;

import React, { useState, useEffect, useRef } from 'react';
import { QuizSet, Question } from './types';
import { extractTextFromFile } from './services/fileService';
import { generateQuizFromText } from './services/geminiService';
import QuizPlayer from './components/QuizPlayer';
import * as fflate from 'fflate';

declare const QRious: any;

const COLORS = [
  'bg-gradient-to-br from-pink-500/20 to-rose-500/20 border-pink-500/30 text-pink-100',
  'bg-gradient-to-br from-blue-500/20 to-indigo-500/20 border-blue-500/30 text-blue-100',
  'bg-gradient-to-br from-amber-500/20 to-orange-500/20 border-amber-500/30 text-amber-100',
  'bg-gradient-to-br from-emerald-500/20 to-teal-500/20 border-emerald-500/30 text-emerald-100',
  'bg-gradient-to-br from-purple-500/20 to-violet-500/20 border-purple-500/30 text-purple-100',
];

/**
 * COMPRESSION UTILS
 */
const compressToCode = (quiz: QuizSet): string => {
  try {
    const minified = [
      2, 
      quiz.title,
      quiz.questions.map(q => [q.question, q.options, q.correctAnswer, q.explanation])
    ];

    const str = JSON.stringify(minified);
    const buf = new TextEncoder().encode(str);
    const compressed = fflate.zlibSync(buf, { level: 9 });

    let binary = "";
    for (let i = 0; i < compressed.length; i++) {
      binary += String.fromCharCode(compressed[i]);
    }
    return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  } catch (e) {
    console.error("Compression error:", e);
    throw new Error("Lỗi nén dữ liệu.");
  }
};

const decompressFromCode = (code: string): QuizSet | null => {
  try {
    let base64 = code.trim().replace(/-/g, '+').replace(/_/g, '/');
    while (base64.length % 4) base64 += '=';

    const binary = atob(base64);
    const buf = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      buf[i] = binary.charCodeAt(i);
    }

    const decompressed = fflate.unzlibSync(buf);
    const str = new TextDecoder().decode(decompressed);
    const data = JSON.parse(str);

    if (Array.isArray(data) && data[0] === 2) {
       return {
         id: `import-${Date.now()}`,
         title: data[1],
         description: "Được chia sẻ qua mã Code",
         questions: data[2].map((q: any, idx: number) => ({
           id: `q-${Date.now()}-${idx}`,
           question: q[0],
           options: q[1],
           correctAnswer: q[2],
           explanation: q[3] || "Không có giải thích chi tiết."
         })),
         createdAt: Date.now(),
         color: COLORS[Math.floor(Math.random() * COLORS.length)]
       };
    }
    // Fallback v1
    if (Array.isArray(data) && data[0] === 1) {
       return {
         id: `import-${Date.now()}`,
         title: data[1],
         description: data[2],
         questions: data[3].map((q: any, idx: number) => ({
           id: `q-${Date.now()}-${idx}`,
           question: q[0],
           options: q[1],
           correctAnswer: q[2],
           explanation: q[3]
         })),
         createdAt: Date.now(),
         color: COLORS[Math.floor(Math.random() * COLORS.length)]
       };
    }

    return null;
  } catch (e) {
    console.error("Decompression error:", e);
    return null;
  }
};

const App: React.FC = () => {
  const [quizzes, setQuizzes] = useState<QuizSet[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeQuiz, setActiveQuiz] = useState<QuizSet | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isMusicPlaying, setIsMusicPlaying] = useState(false);

  // UI States
  const [view, setView] = useState<'HOME' | 'IMPORT' | 'SHARE'>('HOME');
  const [shareData, setShareData] = useState<{code: string, url: string | null} | null>(null);
  const [importCode, setImportCode] = useState('');

  // Multi-QR State
  const [qrChunks, setQrChunks] = useState<string[]>([]);
  const [currentQrIndex, setCurrentQrIndex] = useState(0);

  // Import Multipart State
  const [importParts, setImportParts] = useState<(string | null)[]>([]);
  const [totalImportParts, setTotalImportParts] = useState(0);

  const bgMusic = useRef<HTMLAudioElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    bgMusic.current = new Audio('https://cdn.pixabay.com/audio/2022/05/27/audio_1808fbf07a.mp3');
    bgMusic.current.loop = true;
    bgMusic.current.volume = 0.3;

    const params = new URLSearchParams(window.location.search);
    const sharedCode = params.get('c');
    if (sharedCode) {
      handleImport(sharedCode);
      window.history.replaceState({}, document.title, window.location.pathname);
    }

    const saved = localStorage.getItem('edu_quizzes_v2');
    if (saved) {
      try {
        setQuizzes(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load local storage", e);
      }
    }

    return () => {
      if (bgMusic.current) {
        bgMusic.current.pause();
        bgMusic.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (quizzes.length > 0) {
      localStorage.setItem('edu_quizzes_v2', JSON.stringify(quizzes));
    }
  }, [quizzes]);

  // Effect vẽ QR Code (Hỗ trợ Multi-QR)
  useEffect(() => {
    if (view === 'SHARE' && qrChunks.length > 0 && typeof QRious !== 'undefined') {
      try {
        const qrCanvas = document.getElementById('qr-code');
        if (qrCanvas) {
          // Lấy chunk hiện tại để vẽ
          const valueToEncode = qrChunks[currentQrIndex];

          new QRious({
            element: qrCanvas,
            value: valueToEncode,
            size: 250,
            level: 'L',
            backgroundAlpha: 0,
            foreground: '#ffffff'
          });
        }
      } catch(e) { console.error(e); }
    }
  }, [view, qrChunks, currentQrIndex]);

  const toggleMusic = () => {
    if (!bgMusic.current) return;
    if (isMusicPlaying) {
      bgMusic.current.pause();
    } else {
      bgMusic.current.play().catch(() => {});
    }
    setIsMusicPlaying(!isMusicPlaying);
  };

  // Logic Xử lý Nhập
  const handleImport = (inputCode: string) => {
    if (!inputCode) return;
    const cleanCode = inputCode.trim();

    // Check Multi-QR Format: "MQR|{index}|{total}|{data}"
    // Index bắt đầu từ 1
    if (cleanCode.startsWith("MQR|")) {
      try {
        const [_, idxStr, totalStr, data] = cleanCode.split("|");
        const index = parseInt(idxStr) - 1; // Convert to 0-based
        const total = parseInt(totalStr);

        // Khởi tạo mảng parts nếu chưa có hoặc size khác (reset nếu quét mã mới)
        let newParts = [...importParts];
        if (totalImportParts !== total) {
           newParts = new Array(total).fill(null);
           setTotalImportParts(total);
        }

        newParts[index] = data;
        setImportParts(newParts);
        setImportCode(""); // Clear input

        // Kiểm tra xem đã đủ chưa
        const loadedCount = newParts.filter(p => p !== null).length;
        if (loadedCount === total) {
           // Ghép lại và giải nén
           const fullCode = newParts.join("");
           processFullCode(fullCode);
           // Reset import state
           setImportParts([]);
           setTotalImportParts(0);
        } else {
           alert(`Đã nhập Phần ${index + 1}/${total}. Hãy quét tiếp các phần còn lại!`);
        }

      } catch (e) {
        alert("Mã Multi-QR không hợp lệ.");
      }
      return;
    }

    // Single QR
    processFullCode(cleanCode);
  };

  const processFullCode = (code: string) => {
    const quiz = decompressFromCode(code);
    if (quiz) {
      setQuizzes(prev => {
         if (prev.some(q => q.title === quiz.title && q.questions.length === quiz.questions.length)) return prev;
         return [quiz, ...prev];
      });
      setActiveQuiz(quiz);
      setView('HOME');
      setImportCode('');
      alert(`Đã nhập thành công: ${quiz.title}`);
    } else {
      alert("Mã lỗi hoặc file bị hỏng!");
    }
  };

  const handlePasteAndImport = async () => {
    try {
      const text = await navigator.clipboard.readText();
      setImportCode(text);
      if (text.length > 10) {
          handleImport(text);
      }
    } catch (err) {
      alert("Không thể truy cập bộ nhớ đệm.");
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    setView('HOME');
    setError(null);

    try {
      const text = await extractTextFromFile(file);
      const title = file.name.replace(/\.[^/.]+$/, "");
      const questions = await generateQuizFromText(text, title);

      const newQuiz: QuizSet = {
        id: `quiz-${Date.now()}`,
        title,
        description: `Từ file: ${file.name}`,
        questions,
        createdAt: Date.now(),
        color: COLORS[Math.floor(Math.random() * COLORS.length)],
      };

      setQuizzes(prev => [newQuiz, ...prev]);
    } catch (err: any) {
      setError(err.message || "Lỗi xử lý file.");
    } finally {
      setIsUploading(false);
      event.target.value = '';
    }
  };

  const openShareModal = (quiz: QuizSet, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      const code = compressToCode(quiz);

      // Calculate QR Chunks
      // Zalo safe limit ~ 1500 chars per QR for quick scan
      const MAX_CHUNK_SIZE = 1200; 
      const chunks: string[] = [];

      if (code.length <= MAX_CHUNK_SIZE) {
        chunks.push(code);
      } else {
        const total = Math.ceil(code.length / MAX_CHUNK_SIZE);
        for (let i = 0; i < total; i++) {
          const chunkData = code.slice(i * MAX_CHUNK_SIZE, (i + 1) * MAX_CHUNK_SIZE);
          // Format: MQR|CurrentIndex|Total|Data
          chunks.push(`MQR|${i + 1}|${total}|${chunkData}`);
        }
      }

      setQrChunks(chunks);
      setCurrentQrIndex(0);

      const url = code.length < 2000 
        ? `${window.location.origin}${window.location.pathname}?c=${code}`
        : null;

      setShareData({ code, url });
      setView('SHARE');
    } catch (e) {
      alert("Lỗi tạo mã chia sẻ");
    }
  };

  const deleteQuiz = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Xóa bộ đề này?")) {
      const updated = quizzes.filter(q => q.id !== id);
      setQuizzes(updated);
      localStorage.setItem('edu_quizzes_v2', JSON.stringify(updated));
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-100 relative overflow-hidden flex flex-col">
      {/* Background Effects */}
      <div className="fixed inset-0 pointer-events-none z-0">
         <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-indigo-900/40 rounded-full blur-[100px]"></div>
         <div className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-purple-900/40 rounded-full blur-[100px]"></div>
      </div>

      {/* Top Bar */}
      <nav className="sticky top-0 z-40 bg-slate-900/80 backdrop-blur-md border-b border-white/5 px-4 py-4 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-tr from-indigo-600 to-purple-600 rounded-xl flex items-center justify-center text-white font-black text-xl shadow-lg">
            E
          </div>
          <div className="flex flex-col">
            <h1 className="text-xl font-bold tracking-tight leading-none">EduAI</h1>
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Mobile</span>
          </div>
        </div>
        <button 
            onClick={toggleMusic}
            className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${isMusicPlaying ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/30' : 'bg-white/10 text-slate-400'}`}
          >
            {isMusicPlaying ? '🎧' : '🔇'}
        </button>
      </nav>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-4 pb-32 z-10 scroll-smooth">

        {/* Header Section */}
        {!activeQuiz && view === 'HOME' && (
          <div className="mb-6 mt-2">
             <h2 className="text-2xl font-black mb-1">Thư viện</h2>
             <p className="text-slate-400 text-sm">Học tập thật "Chill" với AI</p>

             {isUploading && (
                <div className="mt-4 p-4 bg-indigo-600/20 rounded-2xl border border-indigo-500/30 flex items-center gap-4 animate-pulse">
                  <div className="w-5 h-5 border-2 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
                  <span className="font-bold text-indigo-300 text-sm">Đang tạo bộ đề...</span>
                </div>
             )}

             {error && (
                <div className="mt-4 p-4 bg-rose-500/20 rounded-2xl border border-rose-500/30 text-rose-300 text-sm">
                  {error}
                </div>
             )}
          </div>
        )}

        {/* Quiz Grid */}
        {view === 'HOME' && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {quizzes.map(quiz => (
              <div 
                key={quiz.id}
                onClick={() => setActiveQuiz(quiz)}
                className={`group relative p-5 rounded-3xl border border-white/5 bg-gradient-to-br from-white/5 to-white/[0.02] hover:border-indigo-500/50 transition-all cursor-pointer active:scale-95`}
              >
